import java.io.IOException; public class EsperarProceso { public EsperarProceso() { try { System.out.println("🚀 Lanzando Calculadora..."); Process proceso = new ProcessBuilder( "open", "-a", "Calculator" ).start(); System.out.println("✅ Calculadora lanzada"); System.out.println("⏳ Java está esperando a que termine el proceso..."); int resultado = proceso.waitFor(); System.out.println("🏁 El proceso ha terminado"); System.out.println("Código de finalización: " + resultado); } catch (IOException | InterruptedException e) { System.out.println("❌ Error: " + e.getMessage()); } } }